<template><div class="page"><div class="page-header"><h2>质检录入</h2></div><el-card shadow="never" style="max-width:550px"><el-form :model="form" label-width="80px" size="small"><el-form-item label="物料编码" required><el-input v-model="form.itemcd" placeholder="输入物料编码"/></el-form-item><el-form-item label="设备SN"><el-input v-model="form.eid" placeholder="设备序列号（选填）"/></el-form-item><el-form-item label="关联单号"><el-input v-model="form.refbillid" placeholder="关联入库单/采购单"/></el-form-item><el-form-item label="质检状态"><el-select v-model="form.qcstatus" style="width:100%"><el-option label="合格" value="1"/><el-option label="不合格" value="0"/></el-select></el-form-item><el-form-item label="备注"><el-input v-model="form.memo" type="textarea" :rows="2"/></el-form-item><el-form-item><el-button type="primary" @click="doSubmit" :loading="saving">提交质检结果</el-button><el-button @click="clearForm">清空</el-button></el-form-item></el-form></el-card></div></template>
<script setup lang="ts">import {reactive,ref} from 'vue';import {ElMessage} from 'element-plus';import {createQcResult} from '@/api/qc'
const form=reactive({itemcd:'',eid:'',refbillid:'',qcstatus:'1',memo:''})
const saving=ref(false)
function clearForm(){form.itemcd='';form.eid='';form.refbillid='';form.qcstatus='1';form.memo=''}
async function doSubmit(){if(!form.itemcd){ElMessage.warning('请输入物料编码');return};saving.value=true;try{await createQcResult({...form});ElMessage.success('录入成功');clearForm()}catch(e:any){ElMessage.error(e?.response?.data?.message||'录入失败')}finally{saving.value=false}}</script>
<style scoped>.page{padding:0}.page-header{display:flex;justify-content:space-between;margin-bottom:16px}.page-header h2{font-size:18px;font-weight:600;margin:0}</style>
